const feature = (title, intro, body, number) => `<section class="proposal-feature${number ? ' numbered-subsection' : ''}"><h3>${number ? `${number} ` : ''}${title}</h3>${intro ? `<p class="feature-intro">${intro}</p>` : ''}${body.replaceAll('<h3>', '<h4>').replaceAll('</h3>', '</h4>')}</section>`;
const detail = (title, body, number) => `<section class="feature-detail${number ? ' numbered-subsection' : ''}"><h3>${number ? `${number} ` : ''}${title}</h3>${body}</section>`;
const list = items => `<ul class="plain-list">${items.map(item => `<li>${item}</li>`).join('')}</ul>`;
const table = (headers, rows) => `<div class="feature-table-wrap"><table class="feature-table"><thead><tr>${headers.map(header => `<th scope="col">${header}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map((cell, index) => index === 0 ? `<th scope="row">${cell}</th>` : `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const demo = (id,label='現有 MathConcept 系統') => `<div class="demo-wrap"><div class="demo-caption">互動示範：${label}</div><div class="demo" data-demo="${id}" id="demo-${id}"></div></div>`;

